css:
.radio-group {
  display: flex;
  flex-direction: column;
  gap: 14px;
  width: 260px;
}

.radio input {
  display: none;
}

.radio {
  position: relative;
  display: flex;
  align-items: center;
  gap: 14px;

  padding: 16px 18px;

  border: 1px solid #ddd;
  border-radius: 14px;

  background: #fff;
  color: #111;

  cursor: pointer;

  overflow: hidden;

  transition:
    transform 0.3s ease,
    border-color 0.3s ease,
    box-shadow 0.3s ease,
    background 0.3s ease;
}

.radio:hover {
  transform: translateX(5px);
  border-color: #111;

  box-shadow: 0 8px 25px rgba(0, 0, 0, 0.08);
}

.radio-circle {
  position: relative;

  width: 22px;
  height: 22px;

  flex-shrink: 0;

  border: 2px solid #111;
  border-radius: 50%;

  transition:
    transform 0.35s ease,
    background 0.35s ease;
}

.radio-circle::after {
  content: "";

  position: absolute;

  width: 8px;
  height: 8px;

  top: 50%;
  left: 50%;

  border-radius: 50%;

  background: #fff;

  transform: translate(-50%, -50%) scale(0);

  transition: transform 0.3s cubic-bezier(0.68, -0.55, 0.27, 1.55);
}

.radio-circle::before {
  content: "";

  position: absolute;

  inset: -7px;

  border: 1px solid #111;
  border-radius: 50%;

  opacity: 0;
  transform: scale(0.4);

  transition:
    transform 0.4s ease,
    opacity 0.4s ease;
}

.radio input:checked + .radio-circle {
  background: #111;
  transform: scale(1.08);
}

.radio input:checked + .radio-circle::after {
  transform: translate(-50%, -50%) scale(1);
}

.radio input:checked + .radio-circle::before {
  opacity: 0.25;
  transform: scale(1);
}

.radio-text {
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.3px;

  transition: transform 0.3s ease;
}

.radio:hover .radio-text {
  transform: translateX(3px);
}

.radio:has(input:checked) {
  background: #111;
  color: #fff;
  border-color: #111;

  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.15);
}

.radio:has(input:checked) .radio-circle {
  border-color: #fff;
}

.radio:has(input:checked) .radio-circle::before {
  border-color: #fff;
}

.radio:active {
  transform: scale(0.97);
}
